"""Build a verified screen manifest and local review gallery after imports finish."""
import hashlib, html, json, pathlib, struct
root=pathlib.Path(__file__).resolve().parent.parent
design=root/'design'
original=json.loads((design/'stitch-screens.json').read_text(encoding='utf-8'))
imports=json.loads((design/'stitch-imported.json').read_text(encoding='utf-8'))
screens=[]
for old in original['screens']:
    code=(design/'stitch'/f"{old['id']}.html").read_bytes()
    png=(design/'stitch'/f"{old['id']}.png").read_bytes()
    fingerprint=hashlib.sha256(code+png).hexdigest()
    matches=[item for item in imports if item['originalId']==old['id'] and item.get('imageMode') and item.get('inputHash')==fingerprint]
    if not matches: raise SystemExit('Awaiting verified import: '+old['title'])
    resource=matches[-1]['screen']
    w,h=struct.unpack('>II',png[16:24])
    screens.append({**old,'originalId':old['id'],'originalName':old['name'],'id':resource['name'].split('/')[-1],'name':resource['name'],'width':w/2,'height':h/2,'localHtml':f"stitch/{old['id']}.html",'localPreview':f"stitch/{old['id']}.png",'htmlCode':resource.get('htmlCode'),'screenshot':resource.get('screenshot')})
manifest={'projectId':original['projectId'],'status':'reviewed design mockups; no application implemented','screens':screens}
(design/'stitch-reviewed-screens.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
cards=[]
for screen in screens:
    title=html.escape(screen['title'])
    cards.append(f'<article><a href="{screen["localPreview"]}"><img loading="lazy" src="{screen["localPreview"]}" alt="{title}"></a><h2>{title}</h2><p>{screen["deviceType"].title()}</p><a href="{screen["localHtml"]}">Open design HTML</a></article>')
gallery='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Explainova — Design Review</title><style>*{box-sizing:border-box}body{margin:0;padding:40px;background:#fbf8ff;color:#171923;font:16px Arial,sans-serif}header{max-width:1100px;margin:0 auto 32px}h1{font-size:38px;letter-spacing:-1px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:24px;max-width:1440px;margin:auto}article{background:#fff;border:1px solid #ddd9ec;border-radius:16px;padding:16px}img{width:100%;height:250px;object-fit:contain;object-position:top;background:#f3f2ff;border-radius:8px}h2{font-size:18px}a{color:#3157ff}p{color:#55506a;line-height:1.6}</style><header><h1>Explainova · Design review</h1><p>20 desktop screens and 10 mobile layouts. Click a preview for the full image, or open its HTML mockup. These are design artifacts, not the connected application.</p><p>The approved homepages remain unchanged in Stitch.</p></header><main>'''+''.join(cards)+'</main></html>'
(design/'index.html').write_text(gallery,encoding='utf-8')
lines=['# Explainova — UI Design Screen Map','','Date: November 6, 2026','','[Open the Stitch project](https://stitch.withgoogle.com/projects/'+original['projectId']+') · [Local review gallery](design/index.html)','','## Scope','','20 desktop screens and 10 mobile layouts extend the approved homepages using the existing Kinetic Editorial design system. The two homepages and design-system asset are preserved. New app frames are arranged below the homepage area: core workflow, account/settings, publishing/recovery, then mobile.','','These are design mockups with HTML references and previews. Authentication, generation, scheduling, and publishing are not connected application functionality. Desktop password/verification forms and secondary recovery patterns should adapt responsively during implementation; the ten explicit mobile frames cover the main flows.','','## Screen inventory','','| Screen | Device | Current Stitch screen ID | Local HTML |','| --- | --- | --- | --- |']
for s in screens: lines.append(f'| {s["title"]} | {s["deviceType"].title()} | `{s["id"]}` | [HTML](design/{s["localHtml"]}) |')
lines+=['','## Main user flow','','```mermaid','flowchart LR','  Home[Approved homepage] --> Auth[Sign in / Create account]','  Auth --> Projects[Private projects]','  Projects --> Plan[Plan]','  Plan --> Storyboard[Storyboard with narration]','  Storyboard --> Generation[Generate]','  Generation --> Review[Review and export]','  Review --> Compose[Publish or schedule]','  Compose --> Calendar[Calendar and post details]','  Projects --> Settings[Profile / Visual defaults]','  Compose --> Connections[Owned social accounts]','```','','## Design and handoff rules','','- Plan → Storyboard → Video is the only authoring stepper; voice is a setting.','- Male/Female options, available voice samples, topic-adaptive themes, captions, previous versions, and explicit final publishing approval.','- 30/60/90-second targets; vertical 1080p/30fps MP4 and SRT.','- No billing, credits, analytics, children-directed modes, shared channels, or decorative tabs inside videos.','- Original homepages are approved references; app screens remain subject to founder review.','- Local text corrections and exact-layout previews were imported using the document/image endpoint used by Google’s Stitch SDK after the MCP edit tool reported changes it did not persist. HTML is included with each imported preview.','- All 30 exported layouts were rendered at their intended 1280px desktop or 390px mobile widths; horizontal overflow checks passed. Representative desktop and mobile screens were visually inspected. This is not a full accessibility or interaction audit.','- Technical, PRD, API, and database contracts take precedence over any remaining illustrative mock data or decorative copy.','','## Source files','','- `design/stitch-reviewed-screens.json`: current remote IDs, original source IDs, dimensions, and local paths.','- `design/stitch/`: reviewed HTML and PNG exports.','- `design/stitch-canvas-backup.json`: original homepage/design-system layout backup.','- The canvas synchronization preserves original frames and updates only the managed app-screen references; older generated alternatives remain available as resources.']
(root/'UI_DESIGN_SCREEN_MAP.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Verified handoff:',len(screens),'screens; local gallery and screen map written.')
